const meta = ($('Split Profiles').first().json || {}).meta || { candidates: [] };
const candidateIds = new Set(meta.candidates.map(c => c.cio_id));
const candidateEmails = new Set(meta.candidates.map(c => c.email));
const picked = $('Pick Duplicates').all().map(i => i.json);
const fetched = $input.all().map(i => i.json || {});
const cutoff = Math.floor(Date.now() / 1000) - 60 * 86400;
const groups = new Map();
let fetchFailed = 0;
picked.forEach((p, idx) => {
  if (p.__none) return;
  const c = (fetched[idx] || {}).customer;
  if (!c || !c.attributes) { fetchFailed++; return; }
  const a = c.attributes;
  if (!groups.has(p.email)) groups.set(p.email, []);
  groups.get(p.email).push({
    isCandidate: candidateIds.has(p.cio_id),
    unsub: c.unsubscribed === true || String(a.unsubscribed) === 'true',
    webform: a.origin === 'user_research_webform',
    recent: Number(a.last_user_research_invite_date) >= cutoff,
    idFormat: /^\d+$/.test(p.id) ? 'numeric' : (/@/.test(p.id) ? 'email as id' : (/^mailchimpid_/.test(p.id) ? 'mailchimp' : 'other'))
  });
});
const size = {};
const formats = {};
let withSiblingUnsub = 0, rule1Blocked = 0, rule1AllowedByWebform = 0, rule2Blocked = 0, anyRuleBlocked = 0;
for (const profiles of groups.values()) {
  size[profiles.length] = (size[profiles.length] || 0) + 1;
  const key = profiles.map(p => p.idFormat).sort().join(' + ');
  formats[key] = (formats[key] || 0) + 1;
  const anyUnsub = profiles.some(p => p.unsub);
  const anyWebform = profiles.some(p => p.webform);
  const anyRecent = profiles.some(p => p.recent);
  if (anyUnsub) withSiblingUnsub++;
  const r1 = anyUnsub && !anyWebform;
  if (r1) rule1Blocked++;
  if (anyUnsub && anyWebform) rule1AllowedByWebform++;
  if (anyRecent) rule2Blocked++;
  if (r1 || anyRecent) anyRuleBlocked++;
}
const total = candidateEmails.size;
const pct = n => total ? Math.round(n * 1000 / total) / 10 : 0;
return [{ json: {
  shards_queried: meta.shardsQueried, shard_statuses: meta.shardStatuses, shard_pages_truncated: meta.shardPagesTruncated,
  candidate_emails: total,
  emails_with_more_than_one_profile: groups.size, pct_duplicated: pct(groups.size),
  profiles_per_duplicated_email: size, id_formats: formats,
  duplicated_with_an_unsubscribed_profile: withSiblingUnsub,
  rule1_should_be_blocked_unsubscribed_no_webform: rule1Blocked, pct_rule1: pct(rule1Blocked),
  rule1_allowed_because_webform: rule1AllowedByWebform,
  rule2_should_be_blocked_recent_invite_on_a_sibling: rule2Blocked, pct_rule2: pct(rule2Blocked),
  candidates_breaking_a_rule_today: anyRuleBlocked, pct_breaking_a_rule: pct(anyRuleBlocked),
  attribute_fetch_failed: fetchFailed, lookup_pages_truncated: (picked[0] || {}).lookupTruncated || 0
} }];

const pages = $input.all().map(i => i.json || {});
const candidates = [];
let truncated = 0;
const statuses = {};
for (const p of pages) {
  statuses[p.statusCode] = (statuses[p.statusCode] || 0) + 1;
  const body = p.body || {};
  if (body.next) truncated++;
  for (const r of (body.identifiers || [])) if (r.email && r.cio_id) candidates.push({ cio_id: r.cio_id, email: String(r.email).trim().toLowerCase() });
}
const emails = Array.from(new Set(candidates.map(c => c.email)));
const out = [];
for (let i = 0; i < emails.length; i += 50) {
  const chunk = emails.slice(i, i + 50);
  out.push({ json: { emails: chunk, body: JSON.stringify({ filter: { or: chunk.map(e => ({ attribute: { field: 'email', operator: 'eq', value: e } })) } }) } });
}
if (!out.length) out.push({ json: { emails: [], body: JSON.stringify({ filter: { attribute: { field: 'email', operator: 'eq', value: 'nobody@invalid.invalid' } } }) } });
out[0].json.meta = { candidates, shardPagesTruncated: truncated, shardStatuses: statuses, shardsQueried: pages.length };
return out;

// Same gates as UXR Search for the n8n users audience, one random shard per query (first page of each shard)
const n = 20;
const set = new Set();
while (set.size < n) set.add(Math.floor(Math.random() * 4096));
return Array.from(set).map(s => ({ json: { shard: s, body: JSON.stringify({ filter: { and: [
  { attribute: { field: 'uxr_shard', operator: 'eq', value: String(s) } },
  { attribute: { field: 'email', operator: 'exists' } },
  { not: { attribute: { field: 'unsubscribed', operator: 'eq', value: 'true' } } },
  { attribute: { field: 'created_n8n_account', operator: 'eq', value: 'true' } },
  { attribute: { field: 'confirmed', operator: 'eq', value: 'true' } },
  { not: { attribute: { field: 'cloud_plan_status', operator: 'eq', value: 'deleted' } } },
  { not: { segment: { id: 260 } } }
] } }) } }));

const pages = $input.all().map(i => i.json || {});
const byEmail = new Map();
let truncated = 0;
for (const p of pages) {
  const body = p.body || {};
  if (body.next) truncated++;
  for (const r of (body.identifiers || [])) {
    const k = String(r.email || '').trim().toLowerCase();
    if (!k || !r.cio_id) continue;
    if (!byEmail.has(k)) byEmail.set(k, []);
    byEmail.get(k).push({ cio_id: r.cio_id, id: String(r.id == null ? '' : r.id) });
  }
}
const out = [];
for (const [email, profiles] of byEmail) {
  if (profiles.length < 2) continue;
  for (const p of profiles) out.push({ json: { email, cio_id: p.cio_id, id: p.id, lookupTruncated: truncated } });
}
if (!out.length) return [{ json: { __none: true, lookupTruncated: truncated } }];
return out.slice(0, 900);
